try:
    _llm_url = cfg.get('llm_proxy_url') or cfg.get('goclaw_url', '')
    if _llm_url and (not _llm_url.rstrip('/').endswith('/chat/completions')):
        _llm_url = _llm_url.rstrip('/') + '/chat/completions'
    async with httpx.AsyncClient(timeout=15.0) as client:
        resp = await client.post(_llm_url, headers={'Authorization': f"Bearer {cfg.get('llm_proxy_token') or cfg.get('goclaw_api_key', '')}", 'Content-Type': 'application/json'}, json={'model': cfg.get('llm_proxy_model') or cfg.get('goclaw_model', ''), 'messages': [{'role': 'user', 'content': prompt}], 'max_tokens': 120, 'temperature': 0})
        resp.raise_for_status()
        content = resp.json()['choices'][0]['message']['content'].strip()
        content = re.sub('^```(?:json)?\\s*|\\s*```$', '', content, flags=re.MULTILINE).strip()
        result = json.loads(content)
        return (result.get('threat', False), result.get('reason', ''))
except Exception as e:
    log.error(f'AI classify error: {e}')
    return (False, '')
